class AnalyticsService {
  recordMetric(name: string, value: number, metadata?: Record<string, any>): void {
    // Simple analytics recording - in production this would send to a real analytics service
    console.log(`Analytics: ${name} = ${value}`, metadata);
    
    // Store locally for now
    const analytics = JSON.parse(localStorage.getItem('analytics') || '[]');
    analytics.push({
      name,
      value,
      metadata,
      timestamp: new Date().toISOString()
    });
    
    // Keep only last 100 events
    if (analytics.length > 100) {
      analytics.splice(0, analytics.length - 100);
    }
    
    localStorage.setItem('analytics', JSON.stringify(analytics));
  }

  getMetrics(): any[] {
    return JSON.parse(localStorage.getItem('analytics') || '[]');
  }

  async getDashboard(): Promise<any> {
    // Mock dashboard data
    return {
      user_id: 'test-user',
      metrics: {
        total_events: 10,
        lessons_completed: 5,
        quizzes_taken: 3,
        average_score: 85
      }
    };
  }

  async getLearningVelocity(period: number): Promise<any> {
    // Mock learning velocity data
    return {
      period_days: period,
      lessons_completed: 5,
      quizzes_taken: 3,
      learning_pace: 'moderate'
    };
  }

  async getStrugglingConcepts(): Promise<any> {
    // Mock struggling concepts data
    return [];
  }

  async getRecommendations(): Promise<any> {
    // Mock recommendations data
    return [];
  }

  async trackEngagementEvent(eventType: string, data: any): Promise<void> {
    // Mock engagement tracking
    console.log('Engagement event:', eventType, data);
  }

  async trackQuizCompleted(quizId: string, score: number, timeSpent: number): Promise<void> {
    // Mock quiz completion tracking
    console.log('Quiz completed:', quizId, score, timeSpent);
  }
}

export const analyticsService = new AnalyticsService();